using Puerts;
using UnityEngine;
public sealed class InventoryJsHost : MonoBehaviour {
  [SerializeField] TextAsset inventoryBundle;
  ScriptEnv env;
  void Awake() {
    env = new ScriptEnv(new BackendV8());
    try { env.Eval(inventoryBundle.text, "inventory-app.js"); }
    catch { env.Dispose(); env = null; throw; }
  }
  void Update() { env?.Tick(); }
  public string Open() => env.Eval<string>("globalThis.inventoryApp.dispatch('open','{}')");
  public string Snapshot() => env.Eval<string>("globalThis.inventoryApp.snapshot()");
  public string CloseWindow() => env.Eval<string>("globalThis.inventoryApp.dispatch('close','{}')");
  void OnDestroy() { env?.Dispose(); env = null; }
}
